import React from "react";
import "./../css/form.css";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

import DatePicker from "react-multi-date-picker";
import persian from "react-date-object/calendars/persian";
import persian_fa from "react-date-object/locales/persian_fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",

      province: "",
      city: "",

      deviceType: "",
      deviceBrand: "",

      deviceIssue: "",
      visitTime: "",
      visitTimeJalali: "",
      description: "",

      states: [],
      cities: [],
      types: [],
      brands: [],

      loadingStates: false,
      loadingCities: false,
      loadingTypesBrands: false,
      submitting: false,

      errors: {},
      success: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.loadStates = this.loadStates.bind(this);
    this.loadCities = this.loadCities.bind(this);
    this.loadTypesBrands = this.loadTypesBrands.bind(this);
    this.handleVisitDateChange = this.handleVisitDateChange.bind(this);
  }

  componentDidMount() {
    this.loadStates();
    this.loadTypesBrands();
  }

  setFieldError(field, message) {
    this.setState((prevState) => ({
      errors: {
        ...prevState.errors,
        [field]: message,
      },
      success: "",
    }));
  }

  clearFieldError(field) {
    this.setState((prevState) => {
      const errors = {
        ...prevState.errors,
      };

      delete errors[field];

      return {
        errors,
        success: "",
      };
    });
  }

  handleChange(field) {
    return (e) => {
      const value = e.target.value;

      this.setState({
        [field]: value,
        success: "",
      });

      this.clearFieldError(field);

      if (field === "province") {
        this.setState({
          city: "",
          cities: [],
        });

        this.clearFieldError("city");

        if (value) {
          this.loadCities(value);
        }
      }
    };
  }

  handleVisitDateChange(date) {
    if (!date) {
      this.setState({
        visitTime: "",
        visitTimeJalali: "",
      });

      this.clearFieldError("visitTime");
      return;
    }

    /*
     * مقدار انتخاب‌شده از دیت‌پیکر شمسی است.
     *
     * برای نمایش:
     * 1405/06/18
     *
     * برای ارسال به API:
     * 2026/09/09
     */

    const jalaliYear = date.year;
    const jalaliMonth = String(date.month).padStart(2, "0");
    const jalaliDay = String(date.day).padStart(2, "0");

    const jalaliDate =
      `${jalaliYear}/${jalaliMonth}/${jalaliDay}`;

    const gregorianDate = date.convert("gregorian");

    const gregorianYear = gregorianDate.year;
    const gregorianMonth = String(gregorianDate.month).padStart(2, "0");
    const gregorianDay = String(gregorianDate.day).padStart(2, "0");

    const gregorianDateFormatted =
      `${gregorianYear}/${gregorianMonth}/${gregorianDay}`;

    this.setState({
      visitTime: gregorianDateFormatted,
      visitTimeJalali: jalaliDate,
    });

    this.clearFieldError("visitTime");
  }

  loadStates() {
    this.setState({
      loadingStates: true,
    });

    const token = localStorage.getItem("token");

    fetch("https://iranaserviceapp.ir/test/api/cities", {
      method: "GET",
      headers: {
        Accept: "application/json",
        ...(token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : {}),
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("HTTP error " + response.status);
        }

        return response.json();
      })
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            states: data.states || [],
            loadingStates: false,
          });
        } else {
          this.setState({
            loadingStates: false,
          });

          this.setFieldError(
            "province",
            data.message || "دریافت استان‌ها انجام نشد"
          );
        }
      })
      .catch((error) => {
        console.error("loadStates error:", error);

        this.setState({
          loadingStates: false,
        });

        this.setFieldError(
          "province",
          "خطا در ارتباط با سرور"
        );
      });
  }

  loadCities(stateId) {
    this.setState({
      loadingCities: true,
      cities: [],
      city: "",
    });

    const token = localStorage.getItem("token");

    fetch(
      `https://iranaserviceapp.ir/test/api/cities?id=${encodeURIComponent(
        stateId
      )}`,
      {
        method: "GET",
        headers: {
          Accept: "application/json",
          ...(token
            ? {
                Authorization: `Bearer ${token}`,
              }
            : {}),
        },
      }
    )
      .then((response) => {
        if (!response.ok) {
          throw new Error("HTTP error " + response.status);
        }

        return response.json();
      })
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            cities: data.cities || [],
            loadingCities: false,
          });
        } else {
          this.setState({
            cities: [],
            loadingCities: false,
          });

          this.setFieldError(
            "city",
            data.message || "دریافت شهرها انجام نشد"
          );
        }
      })
      .catch((error) => {
        console.error("loadCities error:", error);

        this.setState({
          cities: [],
          loadingCities: false,
        });

        this.setFieldError(
          "city",
          "خطا در دریافت شهرها"
        );
      });
  }

  loadTypesBrands() {
    this.setState({
      loadingTypesBrands: true,
    });

    const token = localStorage.getItem("token");

    fetch("https://iranaserviceapp.ir/test/api/list-type", {
      method: "GET",
      headers: {
        Accept: "application/json",
        ...(token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : {}),
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("HTTP error " + response.status);
        }

        return response.json();
      })
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            types: data.types || [],
            brands: data.brands || [],
            loadingTypesBrands: false,
          });
        } else {
          this.setState({
            loadingTypesBrands: false,
          });

          this.setFieldError(
            "deviceType",
            data.message || "دریافت نوع و برند انجام نشد"
          );
        }
      })
      .catch((error) => {
        console.error("loadTypesBrands error:", error);

        this.setState({
          loadingTypesBrands: false,
        });

        this.setFieldError(
          "deviceType",
          "خطا در دریافت نوع و برند دستگاه"
        );
      });
  }

  validateMobile(mobile) {
    const cleanMobile = mobile.replace(/\D/g, "");

    return /^09\d{9}$/.test(cleanMobile);
  }

  validateForm() {
    const {
      fullName,
      mobile,
      province,
      city,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
    } = this.state;

    const errors = {};

    if (!fullName.trim()) {
      errors.fullName = "نام کامل را وارد کنید";
    }

    const cleanMobile = mobile.replace(/\D/g, "");

    if (!cleanMobile) {
      errors.mobile = "شماره موبایل را وارد کنید";
    } else if (!this.validateMobile(mobile)) {
      errors.mobile =
        "شماره موبایل صحیح نیست";
    }

    if (!province) {
      errors.province = "استان را انتخاب کنید";
    }

    if (!city) {
      errors.city = "شهر را انتخاب کنید";
    }

    if (!deviceType) {
      errors.deviceType = "نوع دستگاه را انتخاب کنید";
    }

    if (!deviceBrand) {
      errors.deviceBrand = "برند دستگاه را انتخاب کنید";
    }

    if (!deviceIssue.trim()) {
      errors.deviceIssue = "ایراد دستگاه را وارد کنید";
    }

    if (!visitTime) {
      errors.visitTime = "زمان مراجعه را انتخاب کنید";
    }

    this.setState({
      errors,
      success: "",
    });

    return Object.keys(errors).length === 0;
  }

  handleSubmit(e) {
    e.preventDefault();

    if (!this.validateForm()) {
      return;
    }

    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    const token = localStorage.getItem("token");

    if (!token) {
      this.setState({
        success: "",
      });

      this.setFieldError(
        "mobile",
        "توکن ورود پیدا نشد. لطفاً دوباره وارد حساب کاربری شوید"
      );

      return;
    }

    this.setState({
      submitting: true,
      success: "",
    });

    fetch("https://iranaserviceapp.ir/test/api/create", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        name: fullName.trim(),
        mobile: mobile.replace(/\D/g, ""),
        mobile2: landline.trim(),

        state: province,
        city: city,

        device_brand: deviceBrand,
        device_type: deviceType,

        problem: deviceIssue.trim(),
        description: description.trim(),

        /*
         * تاریخ میلادی
         * مثال:
         * 2026/09/09
         */
        time: visitTime,
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("HTTP error " + response.status);
        }

        return response.json();
      })
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            submitting: false,

            success:
              data.message ||
              "درخواست با موفقیت ثبت شد",

            fullName: "",
            mobile: "",
            landline: "",
            province: "",
            city: "",
            deviceType: "",
            deviceBrand: "",
            deviceIssue: "",
            visitTime: "",
            visitTimeJalali: "",
            description: "",
            cities: [],
            errors: {},
          });
        } else {
          this.setState({
            submitting: false,
          });

          this.setFieldError(
            "deviceIssue",
            data.message ||
              "ثبت درخواست انجام نشد"
          );
        }
      })
      .catch((error) => {
        console.error(
          "create request error:",
          error
        );

        this.setState({
          submitting: false,
        });

        this.setFieldError(
          "deviceIssue",
          "خطا در ارتباط با سرور"
        );
      });
  }

  renderError(field) {
    const { errors } = this.state;

    if (!errors[field]) {
      return null;
    }

    return (
      <div
        style={{
          color: "#dc3545",
          fontSize: "11px",
          marginTop: "-8px",
          marginBottom: "10px",
          paddingRight: "10px",
        }}
      >
        {errors[field]}
      </div>
    );
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTimeJalali,
      description,

      states,
      cities,
      types,
      brands,

      loadingStates,
      loadingCities,
      loadingTypesBrands,
      submitting,

      success,
    } = this.state;

    return (
      <div className="container pt-3">
        <div
          className="mx-auto"
          style={{
            maxWidth: "480px",
          }}
        >
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          <form onSubmit={this.handleSubmit}>
            {/* نام کامل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange(
                  "fullName"
                )}
              />
            </div>

            {this.renderError("fullName")}

            {/* شماره موبایل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                maxLength={11}
                onChange={this.handleChange(
                  "mobile"
                )}
              />
            </div>

            {this.renderError("mobile")}

            {/* تلفن ثابت */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange(
                  "landline"
                )}
              />
            </div>

            {/* استان */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange(
                  "province"
                )}
                disabled={loadingStates}
              >
                <option value="" disabled>
                  {loadingStates
                    ? "در حال دریافت استان‌ها..."
                    : "استان"}
                </option>

                {states.map((state) => (
                  <option
                    key={state.id}
                    value={state.id}
                  >
                    {state.name}
                  </option>
                ))}
              </select>
            </div>

            {this.renderError("province")}

            {/* شهر */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={city}
                onChange={this.handleChange(
                  "city"
                )}
                disabled={
                  !province || loadingCities
                }
              >
                <option value="" disabled>
                  {!province
                    ? "ابتدا استان را انتخاب کنید"
                    : loadingCities
                    ? "در حال دریافت شهرها..."
                    : "شهر"}
                </option>

                {cities.map((item) => (
                  <option
                    key={item.id}
                    value={item.id}
                  >
                    {item.name}
                  </option>
                ))}
              </select>
            </div>

            {this.renderError("city")}

            {/* نوع دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange(
                  "deviceType"
                )}
                disabled={
                  loadingTypesBrands
                }
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "نوع دستگاه"}
                </option>

                {types.map((type) => (
                  <option
                    key={type.id}
                    value={type.id}
                  >
                    {type.name}
                  </option>
                ))}
              </select>
            </div>

            {this.renderError("deviceType")}

            {/* برند دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange(
                  "deviceBrand"
                )}
                disabled={
                  loadingTypesBrands
                }
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "برند دستگاه"}
                </option>

                {brands.map((brand) => (
                  <option
                    key={brand.id}
                    value={brand.id}
                  >
                    {brand.name}
                  </option>
                ))}
              </select>
            </div>

            {this.renderError("deviceBrand")}

            {/* ایراد دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange(
                  "deviceIssue"
                )}
              />
            </div>

            {this.renderError("deviceIssue")}

            {/* زمان مراجعه */}
            <div
              className="custom-input mb-3"
              style={{
                position: "relative",
                overflow: "visible",
              }}
            >
              <div className="custom-icon">
                <FaClock />
              </div>

              <DatePicker
                calendar={persian}
                locale={persian_fa}
                value={visitTimeJalali}
                onChange={
                  this.handleVisitDateChange
                }
                format="YYYY/MM/DD"
                calendarPosition="bottom-right"
                placeholder="زمان مراجعه"
                editable={false}
                inputClass="custom-date-input"
                containerStyle={{
                  width: "100%",
                  position: "relative",
                }}
                style={{
                  width: "100%",
                  height: "100%",
                  border: "none",
                  outline: "none",
                  boxShadow: "none",
                  background: "transparent",
                  fontSize: "14px",
                  fontFamily: "inherit",
                  paddingRight: "10px",
                }}
              />
            </div>

            {this.renderError("visitTime")}

            {/* توضیحات */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange(
                  "description"
                )}
              />
            </div>

            {/* موفقیت - فقط بعد از ثبت */}
            {success && (
              <div
                className="alert alert-success text-center"
                style={{
                  fontSize: "13px",
                  borderRadius: "12px",
                  marginTop: "15px",
                }}
              >
                {success}
              </div>
            )}

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
              disabled={submitting}
            >
              <small>
                {submitting
                  ? "در حال ثبت..."
                  : "ثبت درخواست"}
              </small>
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
